func TestStore_CreateGroup_DuplicateActiveName(t *testing.T) {
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	owner := addTestUser(t, s)
	first, err := s.CreateGroup(ctx, newTestGroup(t, "dupe", owner))
	require.NoError(t, err)

	// Same owner + same name while the first is active => duplicate.
	_, err = s.CreateGroup(ctx, newTestGroup(t, "dupe", owner))
	require.ErrorIs(t, err, store.ErrDuplicatedRecord)

	// UpdateGroupInfo into a taken active name is also a duplicate.
	other, err := s.CreateGroup(ctx, newTestGroup(t, "other", owner))
	require.NoError(t, err)
	err = s.UpdateGroupInfo(ctx, other.Id, "dupe", "")
	require.ErrorIs(t, err, store.ErrDuplicatedRecord)

	// After soft-deleting the first, the name is reusable (partial index only
	// covers non-deleted rows).
	require.NoError(t, s.SoftDeleteGroup(ctx, first.Id))
	reused, err := s.CreateGroup(ctx, newTestGroup(t, "dupe", owner))
	require.NoError(t, err)
	require.NotEmpty(t, reused.Id)
}

func TestStore_RemoveUserFromGroup(t *testing.T) {
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	owner := addTestUser(t, s)
	member := addTestUser(t, s)
	created, err := s.CreateGroup(ctx, newTestGroup(t, "leavers", owner))
	require.NoError(t, err)
	require.NoError(t, s.AddUserToGroup(ctx, created.Id, owner, member))

	require.NoError(t, s.RemoveUserFromGroup(ctx, created.Id, member))

	got, err := s.GetGroupById(ctx, created.Id, owner)
	require.NoError(t, err)
	require.NotContains(t, got.Users, member)
	require.Contains(t, got.Users, owner)

	// The removed member can no longer read the group.
	_, err = s.GetGroupById(ctx, created.Id, member)
	require.ErrorIs(t, err, store.ErrRecordNotFound)

	t.Run("missing/deleted group is not found", func(t *testing.T) {
		require.NoError(t, s.SoftDeleteGroup(ctx, created.Id))
		err := s.RemoveUserFromGroup(ctx, created.Id, owner)
		require.ErrorIs(t, err, store.ErrRecordNotFound)
	})
}

func TestStore_GroupExists(t *testing.T) {
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	owner := addTestUser(t, s)
	created, err := s.CreateGroup(ctx, newTestGroup(t, "exists", owner))
	require.NoError(t, err)

	ok, err := s.GroupExists(ctx, created.Id, owner)
	require.NoError(t, err)
	require.True(t, ok)

	ok, err = s.GroupExists(ctx, created.Id, "outsider")
	require.NoError(t, err)
	require.False(t, ok, "non-members must not see the group as existing")

	require.NoError(t, s.SoftDeleteGroup(ctx, created.Id))
	ok, err = s.GroupExists(ctx, created.Id, owner)
	require.NoError(t, err)
	require.False(t, ok, "a soft-deleted group must not exist")
}
